\section{Introduction}

\subsection{Motivation}
Two research communities have, independently, made central use of the same pair of elementary transcendental functions.

In machine learning, the \emph{rectified linear unit} $x\mapsto\max(x,0)$ is the dominant nonlinearity of deep neural networks. Its non-differentiability at the origin motivates a smooth surrogate, the \emph{softplus} $x\mapsto\log(1+e^x)$, whose derivative is the logistic sigmoid. Practitioners routinely introduce a sharpness parameter $b$ and a linear leak $a$, obtaining the family $E_{a,b}(x)=ax+\log(1+e^{bx})$, and rely---largely on numerical experience---on the family being monotone and convex.

In idempotent analysis and tropical geometry, the \emph{max-plus semiring} $(\R\cup\{-\infty\},\max,+)$ replaces ordinary addition by maximum. Maslov's \emph{dequantization} programme realizes this semiring as a limit of ordinary arithmetic conjugated by exponentials: the family
\[
x\oplus_b y = \tfrac1b\log\bigl(e^{bx}+e^{by}\bigr)
\]
degenerates to $\max$ as $b\to\infty$, with $1/b$ playing the role of a temperature or of Planck's constant.

The observation animating this paper is that these are literally the same expression: with $y=0$,
\[
x\oplus_b 0 = \tfrac1b\log\bigl(1+e^{bx}\bigr) = \frac{E_{0,b}(x)}{b}.
\]
The rescaled softplus is the log-sum-exp of $x$ against the tropical unit. What follows makes both the convex-analytic and the algebraic sides of this identity precise, and quantifies the passage between them.

\subsection{Contributions}
\begin{enumerate}
\item Exact derivative formulas for $E_{a,b}$ in terms of the logistic function (Section~\ref{sec:act}).
\item Global strict convexity of $E_{a,b}$ on $\R$ for every $a$ and every $b\neq 0$ (Theorems~\ref{thm:d2pos},~\ref{thm:strconv}).
\item The sharp monotonicity criterion for $b>0$: strict monotonicity iff $a\geq0$ (Theorem~\ref{thm:monoiff}).
\item Exact commutativity, associativity, distributivity of log-sum-exp, and the exact idempotency defect $(\log2)/b$ (Section~\ref{sec:lse}).
\item The sharp sandwich and dequantization to max-plus and min-plus tropical addition (Section~\ref{sec:sandwich}).
\item A bridge theorem combining all of the above (Section~\ref{sec:bridge}).
\end{enumerate}

\subsection{Notation}
$\log$ and $\exp$ denote the natural logarithm and exponential on $\R$; $\sigma$ denotes the logistic function; $\R_{>0}$ the positive reals. A function $f$ is \emph{strictly convex on a convex set $C$} if $f(\lambda u+(1-\lambda)v) < \lambda f(u)+(1-\lambda)f(v)$ for distinct $u,v\in C$ and $\lambda\in(0,1)$. ``Strictly increasing'' means $u<v\Rightarrow f(u)<f(v)$; ``monotone'' without qualifier means non-decreasing.

\section{The logistic function}

\begin{definition}
The \emph{logistic function} is $\sigma:\R\to\R$, $\sigma(t) = \dfrac{e^t}{1+e^t}$.
\end{definition}

Since $e^t>0$, the denominator satisfies $1+e^t>1>0$, so $\sigma$ is well defined and smooth.

\begin{lemma}[Range]\label{lem:range}
For all $t\in\R$ we have $0<\sigma(t)<1$ and $1-\sigma(t) = \dfrac{1}{1+e^t}$.
\end{lemma}

\begin{proof}
Positivity is a quotient of positive numbers. Since $1+e^t>0$, the inequality $\sigma(t)<1$ is equivalent to $e^t<1+e^t$, i.e.\ to $0<1$. Multiplying $1-\sigma(t)$ by the nonzero quantity $1+e^t$ gives $(1+e^t)-e^t=1$, whence the identity.
\end{proof}

\begin{lemma}[Crude exponential bound]\label{lem:crude}
For all $t$, $\sigma(t)<e^t$.
\end{lemma}

\begin{proof}
Multiplying by $1+e^t>0$ reduces the claim to $e^t<e^t+e^{2t}$, i.e.\ to $0<e^{2t}$.
\end{proof}

\begin{lemma}[Left decay]\label{lem:decay}
$\lim_{t\to-\infty}\sigma(t)=0$.
\end{lemma}

\begin{proof}
$e^t\to0$ as $t\to-\infty$, so $1+e^t\to1\neq0$ and the quotient tends to $0/1=0$. Alternatively squeeze between $0$ and $e^t$ by Lemma~\ref{lem:crude}.
\end{proof}

\begin{lemma}[Logistic differential equation]\label{lem:ode}
$\sigma$ is differentiable with $\sigma'(t)=\sigma(t)\bigl(1-\sigma(t)\bigr)$.
\end{lemma}

\begin{proof}
By the quotient rule, whose denominator never vanishes,
\[
\sigma'(t)=\frac{e^t(1+e^t)-e^{2t}}{(1+e^t)^2}=\frac{e^t}{(1+e^t)^2}
=\frac{e^t}{1+e^t}\cdot\frac{1}{1+e^t}=\sigma(t)\bigl(1-\sigma(t)\bigr),
\]
using Lemma~\ref{lem:range} for the last factor.
\end{proof}

\section{The generalized EML activation: derivatives and convexity}\label{sec:act}

\begin{definition}
For $a,b\in\R$ the \emph{generalized EML activation} is
\[
E_{a,b}:\R\to\R,\qquad E_{a,b}(x)=ax+\log\bigl(1+e^{bx}\bigr).
\]
\end{definition}

The argument of the logarithm is $\geq1>0$, so $E_{a,b}$ is well defined and smooth. Note $E_{a,b}(0)=\log2$ for all $a,b$: every member of the family passes through the same point above the origin. The case $a=0$, $b=1$ is the softplus; $a>0$ gives a residual (leaky) softplus; $E_{0,b}/b$ is the rescaled softplus of sharpness $b$.

\begin{proposition}[First derivative]\label{prop:d1}
$E_{a,b}$ is differentiable everywhere with $E_{a,b}'(x)=a+b\,\sigma(bx)$.
\end{proposition}

\begin{proof}
The map $x\mapsto bx$ has derivative $b$; composing with $\exp$ and adding $1$ shows $x\mapsto1+e^{bx}$ has derivative $b\,e^{bx}$. Since $1+e^{bx}>0$, the chain rule for $\log$ gives
$\frac{d}{dx}\log(1+e^{bx}) = \frac{b e^{bx}}{1+e^{bx}} = b\,\sigma(bx)$.
Adding the derivative $a$ of the linear term completes the proof.
\end{proof}

\begin{proposition}[Second derivative]\label{prop:d2}
$E_{a,b}$ is twice differentiable with $E_{a,b}''(x)=b^2\,\sigma(bx)\bigl(1-\sigma(bx)\bigr)$.
\end{proposition}

\begin{proof}
By Proposition~\ref{prop:d1}, $E_{a,b}'=a+b(\sigma\circ m_b)$ with $m_b(x)=bx$. The chain rule and Lemma~\ref{lem:ode} give $E_{a,b}''(x)=b\cdot\sigma'(bx)\cdot b=b^2\sigma(bx)(1-\sigma(bx))$.
\end{proof}

Two structural facts deserve emphasis. First, the leak parameter $a$ does not appear in the second derivative: adding an affine function changes no curvature. Second, $E_{a,b}''$ depends on $b$ only through $b^2$ and the argument $bx$.

\begin{theorem}[Strictly positive curvature]\label{thm:d2pos}
For every $a\in\R$, every $b\neq0$ and every $x\in\R$, $E_{a,b}''(x)>0$.
\end{theorem}

\begin{proof}
By Lemma~\ref{lem:range}, $0<\sigma(bx)<1$, hence $\sigma(bx)(1-\sigma(bx))>0$. Since $b\neq0$ we have $b^2>0$, and a product of positive reals is positive.
\end{proof}

\begin{theorem}[Global strict convexity]\label{thm:strconv}
For every $a\in\R$ and every $b\neq0$, $E_{a,b}$ is strictly convex on all of $\R$.
\end{theorem}

\begin{proof}
$\R$ is convex, $E_{a,b}$ is continuous and twice differentiable with $E_{a,b}''>0$ everywhere by Theorem~\ref{thm:d2pos}; the second-derivative criterion for strict convexity on a convex set applies.
\end{proof}

\begin{remark}[Sharpness of $b\neq0$]
For $b=0$ we get $E_{a,0}(x)=ax+\log2$, affine: convex but nowhere strictly convex. The parameter domain of strict convexity is thus exactly $\{(a,b):b\neq0\}$.
\end{remark}

\begin{remark}[Curvature magnitude]\label{rem:curv}
Since $\sigma(1-\sigma)$ attains its maximum $1/4$ at $\sigma=1/2$, i.e.\ at $x=0$, we obtain
$0<E_{a,b}''(x)\leq b^2/4$ with equality at $x=0$. Hence $E_{a,b}$ is $\tfrac{b^2}{4}$-smooth, a quantity governing step-size choice in gradient descent. Moreover $\sigma(t)(1-\sigma(t))\le\min(e^t,e^{-t})$, so for $b>0$ the curvature decays exponentially: $E_{a,b}''(x)\le b^2 e^{-b|x|}$.
\end{remark}

\section{The exact monotonicity domain}\label{sec:mono}

Fix $b>0$. Proposition~\ref{prop:d1} confines the derivative to a band,
\[
a < E_{a,b}'(x) < a+b\qquad\text{for all }x,
\]
because $0<\sigma(bx)<1$. Both endpoints are approached but never attained. Monotonicity is therefore decided at the left end.

\begin{theorem}[Sufficiency]\label{thm:suff}
If $a\geq0$ and $b>0$ then $E_{a,b}$ is strictly increasing on $\R$.
\end{theorem}

\begin{proof}
By Proposition~\ref{prop:d1} and Lemma~\ref{lem:range}, $E_{a,b}'(x)=a+b\sigma(bx)>a\geq0$ for every $x$, since $b>0$ and $\sigma(bx)>0$. A differentiable function with everywhere strictly positive derivative on an interval is strictly increasing there.
\end{proof}

\begin{theorem}[Necessity]\label{thm:nec}
If $a<0$ and $b>0$ then $E_{a,b}$ is not monotone (not even non-decreasing).
\end{theorem}

\begin{proof}
Suppose $E_{a,b}$ were non-decreasing. A differentiable non-decreasing function has non-negative derivative, so
\begin{equation}\label{eq:nonneg}
a+b\,\sigma(bx)\geq 0\qquad\text{for all }x\in\R.
\end{equation}
Let $x\to-\infty$. Since $b>0$ we have $bx\to-\infty$, so $\sigma(bx)\to0$ by Lemma~\ref{lem:decay} and the left-hand side of \eqref{eq:nonneg} tends to $a$. A limit of non-negative reals is non-negative, so $a\geq0$, contradicting $a<0$.
\end{proof}

\begin{theorem}[Exact parameter domain for monotonicity]\label{thm:monoiff}
Let $b>0$. Then $E_{a,b}$ is strictly increasing on $\R$ if and only if $a\geq0$.
\end{theorem}

\begin{proof}
Sufficiency is Theorem~\ref{thm:suff}. Conversely, if $a<0$ then $E_{a,b}$ is not non-decreasing by Theorem~\ref{thm:nec}, hence a fortiori not strictly increasing.
\end{proof}

\begin{remark}[Geometry of the failure]\label{rem:fail}
For $a<0$ the equation $E_{a,b}'(x)=0$ reads $\sigma(bx)=-a/b$, which has a unique solution precisely when $0<-a/b<1$, i.e.\ when $-b<a<0$; that solution is
\[
x^{\ast}=\frac1b\log\frac{-a}{a+b},
\]
the unique global minimum of $E_{a,b}$. For $a\leq-b$ the derivative is negative everywhere and $E_{a,b}$ is strictly decreasing. Thus for $b>0$ the parameter line splits into three regimes: strictly increasing ($a\geq0$), unimodal with an interior minimum ($-b<a<0$), and strictly decreasing ($a\leq-b$).
\end{remark}

\begin{remark}[Combined classification]
For $b>0$, the region of the $(a,b)$-plane on which $E_{a,b}$ is simultaneously strictly convex and strictly increasing on all of $\R$ is exactly $\{a\geq0,\;b>0\}$. By the reflection identity $E_{a,b}(x)=E_{a+b,-b}(x)$, which follows from $\log(1+e^t)=t+\log(1+e^{-t})$, the case $b<0$ reduces to $b>0$, and there $E_{a,b}$ is strictly increasing iff $a+b\geq0$.
\end{remark}

\section{Log-sum-exp: exact algebra}\label{sec:lse}

\begin{definition}
For $b\neq0$, the \emph{log-sum-exp} (soft maximum) operation is
\[
x\oplus_b y=\frac1b\log\bigl(e^{bx}+e^{by}\bigr).
\]
\end{definition}

The argument of the logarithm is a sum of positive reals, hence positive, so $\oplus_b$ is well defined.

\begin{lemma}[Transport principle]\label{lem:transport}
Let $\varphi_b(x)=e^{bx}$. For $b\neq0$, $\varphi_b$ is a bijection $\R\to\R_{>0}$ and, for all $x,y$,
\[
\varphi_b(x\oplus_b y)=\varphi_b(x)+\varphi_b(y),\qquad \varphi_b(x+y)=\varphi_b(x)\varphi_b(y).
\]
\end{lemma}

\begin{proof}
The second identity is $e^{b(x+y)}=e^{bx}e^{by}$. For the first, $b(x\oplus_b y)=\log(e^{bx}+e^{by})$ since $b\neq0$ cancels, and exponentiating the logarithm of a positive number returns that number.
\end{proof}

Thus $\varphi_b$ is an isomorphism from $(\R,\oplus_b,+)$ onto $(\R_{>0},+,\times)$: every identity of positive arithmetic in $+$ and $\times$ transports exactly.

\begin{theorem}[Commutativity]
For all $b$ and all $x,y$, $x\oplus_b y=y\oplus_b x$.
\end{theorem}

\begin{proof}
Immediate from commutativity of $+$ inside the logarithm.
\end{proof}

\begin{theorem}[Exact associativity]\label{thm:assoc}
For $b\neq0$ and all $x,y,z$, $(x\oplus_b y)\oplus_b z = x\oplus_b(y\oplus_b z)$.
\end{theorem}

\begin{proof}
Apply $\varphi_b$. By Lemma~\ref{lem:transport} used twice on each side, both images equal $e^{bx}+e^{by}+e^{bz}$. Since $\exp$ is injective and $b\neq0$ may be cancelled, the arguments coincide.
\end{proof}

\begin{theorem}[Distributivity of $+$ over $\oplus_b$]\label{thm:distrib}
For $b\neq0$ and all $x,y,z$, $(x+z)\oplus_b(y+z)=(x\oplus_b y)+z$.
\end{theorem}

\begin{proof}
Inside the logarithm, $e^{b(x+z)}+e^{b(y+z)}=e^{bz}(e^{bx}+e^{by})$. Taking $\log$ of a product of positive factors splits it as $bz+\log(e^{bx}+e^{by})$; dividing by $b$ gives $z+(x\oplus_b y)$.
\end{proof}

\begin{theorem}[Exact idempotency defect]\label{thm:idem}
For $b\neq0$ and all $x$, $\;x\oplus_b x = x + \dfrac{\log 2}{b}$.
\end{theorem}

\begin{proof}
$e^{bx}+e^{bx}=2e^{bx}$; the logarithm of this product of positive numbers is $\log2+bx$; dividing by $b$ gives $x+(\log2)/b$.
\end{proof}

\begin{remark}
Idempotency is the defining axiom of idempotent (tropical) semirings, and it is the unique tropical axiom that $\oplus_b$ violates. Theorem~\ref{thm:idem} quantifies the violation as a constant translation of magnitude $(\log2)/b$, independent of $x$. It is thus natural to regard $1/b$ as a deformation (temperature, Planck) parameter and $b\to\infty$ as a classical, zero-temperature limit.
\end{remark}

\begin{remark}[Absence of a neutral element]
$(\R,\oplus_b)$ has no neutral element, since $x\oplus_b y>\max(x,y)\geq x$ strictly (Theorem~\ref{thm:dom}); the max-plus neutral element $-\infty$ is recovered only in the limit or by extending the domain. This is why $(\R,\oplus_b,+)$ is a \emph{semiring-like} structure: it is the isomorphic image of $(\R_{>0},+,\times)$, which likewise lacks an additive identity.
\end{remark}

\section{The sharp sandwich and dequantization}\label{sec:sandwich}

\begin{theorem}[Strict domination]\label{thm:dom}
For $b>0$ and all $x,y$, $\max(x,y) < x\oplus_b y$.
\end{theorem}

\begin{proof}
Since $b>0$, the claim is equivalent (multiplying by $b$ and exponentiating, both monotone) to $e^{b\max(x,y)}<e^{bx}+e^{by}$. By symmetry assume $x\leq y$; then the right-hand side is $e^{by}+e^{bx}>e^{by}$ because $e^{bx}>0$.
\end{proof}

\begin{theorem}[Sharp upper bound]\label{thm:upper}
For $b>0$ and all $x,y$, $\;x\oplus_b y\leq\max(x,y)+\dfrac{\log2}{b}$.
\end{theorem}

\begin{proof}
Let $m=\max(x,y)$. Since $b>0$, both $e^{bx}\leq e^{bm}$ and $e^{by}\leq e^{bm}$, so $e^{bx}+e^{by}\leq2e^{bm}$. Applying the increasing function $\log$ and using $\log(2e^{bm})=\log2+bm$ gives $\log(e^{bx}+e^{by})\leq(m+\tfrac{\log2}{b})b$; divide by $b>0$.
\end{proof}

\begin{corollary}[Sharpness and exact expansion]\label{cor:sharp}
The constant $\log2$ in Theorem~\ref{thm:upper} cannot be decreased: equality holds throughout whenever $x=y$, by Theorem~\ref{thm:idem}. Moreover, for all $x,y$,
\[
x\oplus_b y = \max(x,y) + \frac1b\log\bigl(1+e^{-b|x-y|}\bigr),
\]
so the error decays from $(\log2)/b$ at $x=y$ to $0$ exponentially fast in $b|x-y|$.
\end{corollary}

\begin{proof}
With $m=\max(x,y)$ and $d=|x-y|$, factor $e^{bx}+e^{by}=e^{bm}(1+e^{-bd})$ and take logarithms.
\end{proof}

\begin{theorem}[Maslov dequantization, max-plus form]\label{thm:deq}
For all $x,y\in\R$, $\;\lim_{b\to+\infty} x\oplus_b y = \max(x,y)$.
\end{theorem}

\begin{proof}
Squeeze: for all $b>0$, Theorems~\ref{thm:dom} and \ref{thm:upper} give $\max(x,y)\leq x\oplus_b y\leq\max(x,y)+(\log2)/b$, and both bounds tend to $\max(x,y)$.
\end{proof}

\begin{theorem}[Min-plus form]\label{thm:trop}
For all $x,y\in\R$, $\;\lim_{b\to+\infty}\bigl(-\bigl((-x)\oplus_b(-y)\bigr)\bigr)=\min(x,y)$, the addition of the tropical semiring in its min-plus convention.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:deq} at $(-x,-y)$, $(-x)\oplus_b(-y)\to\max(-x,-y)$; negation is continuous, so the left-hand side converges to $-\max(-x,-y)=\min(x,y)$.
\end{proof}

\begin{remark}[Uniformity and the $n$-ary case]
The bound of Theorem~\ref{thm:upper} is uniform in $(x,y)$: the error $x\oplus_b y-\max(x,y)$ lies in $(0,(\log2)/b]$ for every pair. Hence the convergence in Theorem~\ref{thm:deq} is uniform on $\R^2$, with sup-norm rate exactly $\Theta(1/b)$. The same argument with $n$ summands gives $\max_i x_i<\frac1b\log\sum_{i=1}^n e^{bx_i}\leq\max_i x_i+\frac{\log n}{b}$.
\end{remark}

\section{The bridge theorem}\label{sec:bridge}

\begin{lemma}[Activation equals log-sum-exp against the tropical unit]\label{lem:actlse}
For every $b\neq0$ and every $x$, $\;\dfrac{E_{0,b}(x)}{b} = x\oplus_b 0$.
\end{lemma}

\begin{proof}
$E_{0,b}(x)=\log(1+e^{bx})$ and $x\oplus_b0=\frac1b\log(e^{bx}+1)$; commutativity of addition inside the logarithm identifies the two.
\end{proof}

Write $S_b(x):=E_{0,b}(x)/b=\frac1b\log(1+e^{bx})$ for the rescaled activation of sharpness $b>0$.

\begin{theorem}[EML activation--tropical bridge]\label{thm:bridge}
Let $b>0$. Then:
\begin{enumerate}
\item $E_{0,b}$, and hence $S_b$, is strictly convex on all of $\R$;
\item $E_{0,b}$, and hence $S_b$, is strictly increasing on $\R$ (the boundary case $a=0$ of the exact monotonicity domain $a\geq0$);
\item $\max(x,0) < S_b(x)$ for every $x\in\R$;
\item $S_b(x)\leq\max(x,0)+\dfrac{\log2}{b}$ for every $x\in\R$;
\item $\displaystyle\lim_{c\to\infty}\frac{E_{0,c}(x)}{c}=\max(x,0)$ for every $x\in\R$.
\end{enumerate}
\end{theorem}

\begin{proof}
(1) is Theorem~\ref{thm:strconv} with $a=0$, $b\neq0$; scaling by $1/b>0$ preserves strict convexity. (2) is Theorem~\ref{thm:suff} with $a=0$. (3) and (4) follow from Lemma~\ref{lem:actlse} together with Theorems~\ref{thm:dom} and~\ref{thm:upper} at $y=0$. (5) follows from Lemma~\ref{lem:actlse}, valid for every $c\neq0$, together with Theorem~\ref{thm:deq} at $y=0$.
\end{proof}

\begin{remark}[Loss of strictness in the limit]
The limit $R(x)=\max(x,0)$ is convex and non-decreasing but nowhere strictly convex (affine on $(-\infty,0]$ and on $[0,\infty)$) and not strictly increasing (constant on $(-\infty,0]$). Items (1)--(2) hold for every finite $b$ and fail in the limit: strictness is lost exactly at $b=\infty$, mirroring the fact that idempotency is achieved only in the limit. Equivalently, $S_b''(x)=b\,\sigma(bx)(1-\sigma(bx))$ has total mass $\int_{\R}S_b''=1$ independent of $b$ and converges weakly to the Dirac mass $\delta_0$: all curvature concentrates at the origin, becoming the corner.
\end{remark}

\begin{remark}[Exact sup-norm distance]
Items (3)--(4) say the graph of $S_b$ lies in a horizontal band of height $(\log2)/b$ above the graph of the rectifier, everywhere. Equivalently $\|S_b-R\|_\infty=(\log2)/b$, attained at $x=0$, where $S_b(0)=(\log2)/b$ and $R(0)=0$: the distance is known exactly, not merely bounded.
\end{remark}

\section{Algorithms}

\subsection{Numerically stable evaluation}
Direct evaluation of $\frac1b\log(e^{bx}+e^{by})$ overflows when $b\max(x,y)$ exceeds the floating-point exponent range (about $709$ in IEEE double precision). The stable form is exactly the expansion of Corollary~\ref{cor:sharp},
\[
x\oplus_b y = m+\frac1b\log\bigl(1+e^{-b|x-y|}\bigr),\qquad m=\max(x,y),
\]
whose exponential argument is always $\leq0$, so no overflow can occur; $\log(1+u)$ should be evaluated with a dedicated \texttt{log1p} primitive to avoid cancellation. The cost is $O(1)$ operations with one exponential and one logarithm. Likewise
\[
S_b(x)=\max(x,0)+\tfrac1b\,\mathrm{log1p}\bigl(e^{-b|x|}\bigr),
\]
manifestly the rectifier plus a strictly positive correction bounded by $(\log2)/b$.

\subsection{Sharpness selection from an error tolerance}
Given a target uniform accuracy $\varepsilon>0$ for approximating the rectifier,
\[
\|S_b-R\|_\infty = \frac{\log2}{b}\leq\varepsilon \iff b\geq\frac{\log2}{\varepsilon},
\]
so the minimal admissible sharpness is $b^\ast=(\log2)/\varepsilon$, and it is optimal since the error at $x=0$ equals $(\log2)/b$ exactly. The corresponding maximal curvature is $\sup_x S_b''(x)=b/4=\log2/(4\varepsilon)$, exposing the trade-off: accuracy $\varepsilon$ costs curvature of order $1/\varepsilon$.

\subsection{Monotonicity certification}
For $b>0$, deciding whether $E_{a,b}$ is strictly increasing is, by Theorem~\ref{thm:monoiff}, the single comparison $a\geq0$: an $O(1)$ test requiring no numerical analysis. When $-b<a<0$ the failure is localized at $x^\ast=\frac1b\log\frac{-a}{a+b}$ (Remark~\ref{rem:fail}), turning a qualitative failure into an actionable diagnostic.

\section{Applications and discussion}

\subsection{Neural network design}
Three concrete guarantees follow for architectures built on EML activations. \emph{Convexity is free}: any activation $ax+\log(1+e^{bx})$ with $b\neq0$ is strictly convex whatever the leak $a$, so in input-convex architectures---where convexity in the inputs is enforced by convex non-decreasing activations and non-negative weights---this half of the requirement is automatic. \emph{Monotonicity has a sharp threshold}: the other half holds exactly when $a\geq0$; a leak of $a=-10^{-6}$ genuinely produces a non-monotone activation with a minimum at $x^\ast=\frac1b\log\frac{-a}{a+b}$. \emph{Smoothing is quantitatively controlled}: replacing a rectifier by $S_b$ changes each neuron's output by at most $(\log2)/b$, uniformly; propagating through a depth-$d$ network of $1$-Lipschitz layers gives a total drift $O(d\log2/b)$.

\subsection{Tropical geometry of networks}
A rectifier network computes a piecewise-linear function, i.e.\ in the tropical dictionary a tropical rational function: a difference of two tropical polynomials. Its linear regions correspond to vertices of a Newton polytope. Theorem~\ref{thm:bridge} supplies the analytic half of the dictionary: the smoothed network is an analytic deformation of the tropical object with an explicit modulus of convergence, so $1/b$ acts as a resolution parameter interpolating between a differentiable model and a combinatorial one.

\subsection{Statistical mechanics and optimization}
With $b=1/T$ the inverse temperature, $x\oplus_b y$ is the free energy of a two-state system with energies $-x,-y$; the sandwich of Section~\ref{sec:sandwich} says the free energy lies between the ground-state energy and that energy plus $T\log2$, the entropy of two degenerate states, and the $n$-ary form recovers $T\log n$. In optimization, $\oplus_b$ is the value of the linear program $\max_i x_i$ regularized by $\frac1b$ times a Shannon entropy penalty, whose maximal value is exactly $(\log2)/b$.

\subsection{Other EML activations}
The method---differentiate twice, recognize the logistic factor, read off signs, take a limit at $-\infty$ for necessity---applies verbatim elsewhere. The Swish/SiLU activation $x\sigma(bx)$ is not monotone for any $b>0$ and has a second derivative that changes sign. For $ax+\frac1b\log\cosh(bx)$ the derivative $a+\tanh(bx)$ ranges over $(a-1,a+1)$, so the activation is strictly increasing on $\R$ iff $a\geq1$, while its second derivative $b\sech^2(bx)$ is positive for every $b>0$; its $b\to\infty$ limit is $ax+|x|$. Mish, $x\tanh(\log(1+e^{bx}))$, is a composite of two EML transcendentals with a correspondingly richer critical-point structure.

\section{Future work}

\begin{enumerate}
\item \textbf{$n$-ary and measure-theoretic log-sum-exp.} Replace $\oplus_b$ by $\frac1b\log\sum_{i<n}e^{bx_i}$ and by $\frac1b\log\int e^{bf}\,d\mu$; the sandwich becomes $\max\leq\cdot\leq\max+\frac{\log n}{b}$, respectively an essential-supremum statement, yielding $L^p\to L^\infty$ style dequantization.
\item \textbf{Joint convexity.} Show $(x,y)\mapsto x\oplus_b y$ is convex but not strictly convex, being affine along the diagonal $x=y$; the tropical limit $\max$ is convex and affine on each of two half-planes.
\item \textbf{The deformed semirings as objects.} Treat $(\R,\oplus_b,+)$ as a family of algebraic structures transported from $\R_{>0}$ and prove convergence to the tropical semiring, in a Gromov--Hausdorff sense or via pointwise convergence of structure maps.
\item \textbf{From one neuron to an architecture.} Quantify the uniform distance between a $b$-smoothed network of depth $d$ and its tropical limit; an $O(d\log(\text{width})/b)$ bound would extend Theorem~\ref{thm:bridge} to whole architectures.
\item \textbf{Sharp domains for other EML activations.} Carry out the exact analysis for Swish, Mish and the $\log\cosh$ family and identify their piecewise-linear limits.
\item \textbf{Rate optimality.} Prove $(\log2)/b$ cannot be replaced by $c/b$ with $c<\log2$, and develop the expansion of Corollary~\ref{cor:sharp} into an asymptotic series.
\end{enumerate}

\section{Conclusion}

We determined the exact parameter domain of monotonicity and convexity for $E_{a,b}(x)=ax+\log(1+e^{bx})$: strict convexity on the whole real line for every $a$ and every $b\neq0$, and---for $b>0$---strict monotonicity if and only if $a\geq0$, the latter established by a limit argument showing that a negative leak destroys even weak monotonicity. The same exponential--logarithmic pairing generates the log-sum-exp operation, which satisfies commutativity, associativity and distributivity over ordinary addition exactly, being the transport of positive arithmetic along $x\mapsto e^{bx}$, and which violates idempotency by the exactly computable constant $(\log2)/b$. The two-sided sandwich then yields Maslov dequantization to tropical addition with an explicit, uniform and optimal rate. Specializing to the tropical unit closes the loop: $S_b(x)=\frac1b\log(1+e^{bx})$ is strictly convex and strictly increasing for every finite $b>0$, strictly dominates $\max(x,0)$, lies within $(\log2)/b$ of it uniformly, and converges to it---losing both strictness properties precisely in the limit.

