function CLASSIFY(a, b) → report:
    if b = 0:
        return (affine; increasing iff a > 0; decreasing iff a < 0; curvature 0)

    # reduce to positive sharpness via the identity E_{a,b} = E_{a+b,−b}
    if b > 0: (aₑ, bₑ) ← (a, b)  else  (aₑ, bₑ) ← (a + b, −b)

    strictly_convex     ← TRUE                       # holds for every b ≠ 0
    strictly_increasing ← (aₑ ≥ 0)                   # sharp threshold
    strictly_decreasing ← (aₑ + bₑ ≤ 0)
    critical_point      ← NONE
    if −bₑ < aₑ < 0:
        critical_point  ← log(−aₑ / (aₑ + bₑ)) / bₑ   # unique global minimum

    derivative_limit_at_−∞ ← aₑ
    derivative_limit_at_+∞ ← aₑ + bₑ
    peak_curvature          ← b² / 4                  # attained at x = 0
    return report

function MINIMAL_SHARPNESS(ε):                       # ε > 0
    return log(2) / ε
    # optimal: the error at x = 0 equals log(2)/b exactly, so no smaller b works

function CALIBRATION(ε):
    b* ← MINIMAL_SHARPNESS(ε)
    return (sharpness b*, peak curvature b*/4, admissible step size 4/b*)
